// Expression plotter: your own functions, with a slider for every parameter.
//
// Generated by Formula from the rows of an Expression plotter. Explicit rows are
// y = f(x), polar rows are r = f(theta), parametric rows are (x(t), y(t)). The
// parts between the @ markers are what changes from one export to the next.
// Each parameter gets a range input under the canvas; drag to pan, scroll to zoom.
//
// Self-contained: compile with `tsc main.ts` and load main.js in any HTML page
// (it creates its own <canvas>), or paste into a TypeScript playground.

type Params = Record<string, number>;
type Row =
  | { kind: "explicit"; f: (x: number) => number }
  | { kind: "curve"; f: (t: number) => [number, number]; t0: number; t1: number };

const params: Record<string, { value: number; min: number; max: number }> = {
// @PARAMS
  a: { value: 2.0, min: -10.0, max: 10.0 },
  b: { value: 1.0, min: -10.0, max: 10.0 },
  k: { value: 3.0, min: -10.0, max: 10.0 },
// @END
};

/** A polar point (r, theta) as (x, y). */
function polar(r: number, theta: number): [number, number] {
  return [r * Math.cos(theta), r * Math.sin(theta)];
}

/** Every row of the plot, for the current parameter values. */
function rows(p: Params): Row[] {
// @EXPRESSIONS
  const { a, b, k } = p;
  return [
    { kind: "explicit", f: (x: number) => a * Math.sin(b * x) },
    { kind: "curve", f: (theta: number) => polar(1 + Math.cos(k * theta), theta), t0: 0.0, t1: 6.283185307179586 },
  ];
// @END
}

const COLORS = ["#9db3ff", "#5cc2b2", "#e3a93b"];
const canvas = document.createElement("canvas");
canvas.width = 800;
canvas.height = 600;
canvas.style.background = "#16201c";
document.body.appendChild(canvas);
const ctx = canvas.getContext("2d")!;

// One labelled range input per parameter.
for (const [name, p] of Object.entries(params)) {
  const label = document.createElement("label");
  label.style.display = "block";
  label.style.fontFamily = "monospace";
  const input = document.createElement("input");
  input.type = "range";
  input.min = String(p.min);
  input.max = String(p.max);
  input.step = "any";
  input.value = String(p.value);
  const shown = document.createElement("span");
  shown.textContent = ` ${name} = ${p.value.toFixed(2)}`;
  input.addEventListener("input", () => {
    p.value = Number(input.value);
    shown.textContent = ` ${name} = ${p.value.toFixed(2)}`;
  });
  label.append(input, shown);
  document.body.appendChild(label);
}

// The view: world center and world units per pixel.
const view = { cx: 0, cy: 0, scale: 0.01 };
let drag: { x: number; y: number } | null = null;
canvas.addEventListener("pointerdown", (e) => (drag = { x: e.offsetX, y: e.offsetY }));
canvas.addEventListener("pointermove", (e) => {
  if (drag === null) return;
  view.cx -= (e.offsetX - drag.x) * view.scale;
  view.cy += (e.offsetY - drag.y) * view.scale;
  drag = { x: e.offsetX, y: e.offsetY };
});
window.addEventListener("pointerup", () => (drag = null));
canvas.addEventListener("wheel", (e) => {
  e.preventDefault();
  view.scale *= Math.exp(e.deltaY * 0.001);
});

const toScreen = (x: number, y: number): [number, number] => [
  canvas.width / 2 + (x - view.cx) / view.scale,
  canvas.height / 2 - (y - view.cy) / view.scale,
];

/** Draws a polyline, lifting the pen where a point is not finite or jumps
 *  by more than five view heights (an asymptote). */
function curve(points: [number, number][], color: string, dashed: boolean): void {
  const span = canvas.height * view.scale;
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.setLineDash(dashed ? [7, 5] : []);
  ctx.beginPath();
  let prev: [number, number] | null = null;
  for (const [x, y] of points) {
    if (!Number.isFinite(x) || !Number.isFinite(y)) {
      prev = null;
      continue;
    }
    const [sx, sy] = toScreen(x, Math.max(-1e6, Math.min(1e6, y)));
    if (prev === null || Math.abs(y - prev[1]) > 5 * span) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
    prev = [x, y];
  }
  ctx.stroke();
  ctx.setLineDash([]);
}

function frame(): void {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const [ox, oy] = toScreen(0, 0);
  ctx.strokeStyle = "#55635d";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(0, oy);
  ctx.lineTo(canvas.width, oy);
  ctx.moveTo(ox, 0);
  ctx.lineTo(ox, canvas.height);
  ctx.stroke();

  const p: Params = {};
  for (const [name, q] of Object.entries(params)) p[name] = q.value;
  rows(p).forEach((row, i) => {
    const points: [number, number][] = [];
    if (row.kind === "explicit") {
      for (let px = 0; px <= canvas.width; px++) {
        const x = view.cx + (px - canvas.width / 2) * view.scale;
        points.push([x, row.f(x)]);
      }
    } else {
      const steps = 720;
      for (let j = 0; j <= steps; j++) points.push(row.f(row.t0 + ((row.t1 - row.t0) * j) / steps));
    }
    curve(points, COLORS[i % 3], i >= 3);
  });
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
